template:
import React from 'react';

export function Button({ label, variant = 'primary', disabled = false, loading = false, onClick }: {
  label: string;
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  disabled?: boolean;
  loading?: boolean;
  onClick?: () => void;
}) {
  const base = {
    primary: { background: '{{token:colors.accent.primary}}', color: '{{token:colors.text.inverse}}', border: '1px solid {{token:colors.accent.primary}}' },
    secondary: { background: '{{token:colors.base.surface}}', color: '{{token:colors.text.primary}}', border: '1px solid {{token:colors.base.border}}' },
    danger: { background: '{{token:colors.accent.danger}}', color: '{{token:colors.text.inverse}}', border: '1px solid {{token:colors.accent.danger}}' },
    ghost: { background: 'transparent', color: '{{token:colors.accent.primary}}', border: '1px solid transparent' },
  };
  return (
    <button
      type="button"
      aria-disabled={disabled || loading}
      disabled={disabled || loading}
      onClick={onClick}
      style={{
        ...base[variant],
        padding: '{{token:spacing.sidebar.padding}}',
        borderRadius: '{{token:spacing.card.borderRadius}}',
        fontSize: '{{token:typography.scale.sm}}',
        fontWeight: 600,
        cursor: disabled || loading ? 'not-allowed' : 'pointer',
        opacity: disabled || loading ? 0.6 : 1,
        transition: '{{token:animation.transition.default}}',
      }}
      onFocus={(e) => { e.currentTarget.style.outline = '2px solid {{token:colors.accent.primary}}'; e.currentTarget.style.outlineOffset = '2px'; }}
      onBlur={(e) => { e.currentTarget.style.outline = 'none'; }}
    >
      {loading ? '…' : label}
    </button>
  );
}

loading.template:
import React from 'react';

export function Button({ label }: { label: string }) {
  return <button aria-busy="true" disabled style={{ background: '{{token:colors.accent.primary}}', color: '{{token:colors.text.inverse}}', padding: '{{token:spacing.sidebar.padding}}', borderRadius: '{{token:spacing.card.borderRadius}}', opacity: 0.6 }}>{label}…</button>;
}
